SELECT SUM(CAST(total_fee AS SIGNED))
FROM trade
WHERE CAST(company_id AS SIGNED) = #{companyId}
	AND trade_state IN ('REFUND_PROCESS', 'REFUND_SUCCESS', 'SUCCESS')
	AND CAST(time_expire AS SIGNED) >= #{startSec}
	AND CAST(time_expire AS SIGNED) <= #{endSec}

SELECT COUNT(*)
FROM trade
WHERE CAST(company_id AS SIGNED) = #{companyId}
	AND trade_state IN ('REFUND_PROCESS', 'REFUND_SUCCESS', 'SUCCESS')
	AND CAST(time_expire AS SIGNED) >= #{startSec}
	AND CAST(time_expire AS SIGNED) <= #{endSec}

